// normalizeProviders.js — pure-JS provider-response → common candidate shape.
//
// toCandidates(providerName, rawResponse, objectType) flattens ONE provider's raw
// API response into an array of common-shape candidates, one per usable field:
//   { field, source, value, normalizedValue, accuracy, recencyDate }
// where `field` is the canonical HubSpot property, `value` is the raw provider
// value, `normalizedValue` is the cross-check key (E.164 phone / lowercased email /
// revenue band / employee band / NAICS code), `accuracy` (0-1) is derived from the
// provider's per-field quality signal (see ENRICHMENT-WORKFLOW-PLAN.md §2 A-table),
// and `recencyDate` is the field's freshness date for the recency term.
//
// NO npm. Reuses normalizePhoneAU / normalizeEmailBasic from siblings. Revenue and
// employee band normalizers are local (mirror src/normalizer.py) — small enough to
// keep here rather than import a fourth module.


// ---- local value normalizers (mirror src/normalizer.py band logic) ----------
// Parse a revenue value (number OR range string like "10M-25M") to lower-bound
// dollars, then map to the CLAUDE.md revenue bands. Range strings use the LOWER
// bound so "10M-25M" -> 5-50M, "50M-100M" -> 50-500M.
function _revenueToDollars(value) {
  if (value === null || value === undefined || value === "") return null;
  if (typeof value === "number") return value;
  const s = String(value);
  const m = s.match(/([\d.]+)\s*([kmb]?)/i); // first magnitude
  if (!m) return null;
  let n = parseFloat(m[1]);
  if (Number.isNaN(n)) return null;
  const unit = (m[2] || "").toLowerCase();
  if (unit === "k") n *= 1e3;
  else if (unit === "m") n *= 1e6;
  else if (unit === "b") n *= 1e9;
  return n;
}

function normalizeRevenueBand(value) {
  const v = _revenueToDollars(value);
  if (v === null) return null;
  if (v < 1e6) return "<1M";
  if (v < 5e6) return "1-5M";
  if (v < 50e6) return "5-50M";
  if (v < 500e6) return "50-500M";
  if (v < 750e6) return "500-750M";
  if (v < 1e9) return "750M-1B";
  if (v < 1.2e9) return "1B-1.2B";
  return "1.2B+";
}

function normalizeEmployeeBand(value) {
  if (value === null || value === undefined || value === "") return null;
  // Already a band string (e.g. ZoomInfo employeeRange "201-500") -> pass through.
  if (typeof value === "string" && !/^\d+$/.test(value.trim())) return value.trim();
  const v = parseInt(value, 10);
  if (Number.isNaN(v)) return null;
  if (v <= 9) return "1-9";
  if (v <= 50) return "10-50";
  if (v <= 200) return "51-200";
  if (v <= 500) return "201-500";
  if (v <= 1000) return "501-1000";
  return "1001+";
}

function normalizeCountryRegion(value) {
  if (!value) return null;
  const v = String(value).trim().toLowerCase();
  if (["australia", "au", "aus"].includes(v)) return "AU";
  if (["new zealand", "nz"].includes(v)) return "NZ";
  return "Other";
}

function _clamp01(n) {
  if (n < 0) return 0;
  if (n > 1) return 1;
  return n;
}

// ---- per-provider accuracy helpers (ENRICHMENT-WORKFLOW-PLAN.md §2) ---------
const APOLLO_EMAIL_A = { verified: 1.0, guessed: null, pending: 0.3, unavailable: 0, bounced: 0 };

function apolloEmailAccuracy(raw) {
  const status = raw.email_status;
  let a;
  if (status === "guessed") {
    // guessed = 0.5 * extrapolated_confidence (default confidence 1.0 when absent).
    let ex = raw.extrapolated_email_confidence;
    if (ex === null || ex === undefined) ex = 1.0;
    if (ex > 1) ex = ex / 100; // tolerate 0-100 scale
    a = 0.5 * ex;
  } else {
    a = APOLLO_EMAIL_A[status];
    if (a === null || a === undefined) a = 0; // unknown status -> no trust
  }
  if (raw.email_domain_catchall) a *= 0.6; // catchall penalty
  return _clamp01(a);
}

const LUSHA_EMAIL_CONF = { "A+": 1.0, A: 0.8 };
function lushaEmailAccuracy(e) {
  let a = LUSHA_EMAIL_CONF[e.confidence];
  if (a === null || a === undefined) a = 0.4; // null/unknown grade
  if (e.type && String(e.type).toLowerCase() !== "work") a *= 0.8; // private/personal
  return _clamp01(a);
}

// ---- provider mappers -------------------------------------------------------
function _push(out, field, source, value, normalizedValue, accuracy, recencyDate) {
  if (value === null || value === undefined || value === "") return;
  out.push({ field, source, value, normalizedValue, accuracy: _clamp01(accuracy), recencyDate: recencyDate || null });
}

function lushaCandidates(raw, objectType) {
  const out = [];
  const src = "lusha";
  if (objectType === "contacts") {
    for (const e of raw.emails || []) {
      _push(out, "email", src, e.email, normalizeEmailBasic(e.email), lushaEmailAccuracy(e), e.updateDate);
    }
    for (const p of raw.phones || []) {
      if (p.doNotCall) continue; // suppress (not just downscore) per §2
      const t = String(p.type || "").toLowerCase();
      const acc = t === "mobile" || t === "direct" ? 0.8 : 0.5;
      const field = t === "mobile" ? "mobilephone" : "phone";
      _push(out, field, src, p.number, normalizePhoneAU(p.number), acc, p.updateDate);
    }
    if (raw.jobTitle) {
      // No per-field grade for Lusha title -> ungraded base 0.6.
      _push(out, "jobtitle", src, raw.jobTitle.title, _norm(raw.jobTitle.title), 0.6, raw.updateDate);
      _push(out, "seniority", src, raw.jobTitle.seniority, _norm(raw.jobTitle.seniority), 0.6, raw.updateDate);
    }
  } else {
    // company firmographics — no per-field grade -> base 0.6.
    _push(out, "lv_revenue_band", src, raw.revenueRange, normalizeRevenueBand(raw.revenueRange), 0.6, raw.updateDate);
    _push(out, "lv_employee_band", src, raw.employeeCount, normalizeEmployeeBand(raw.employeeCount), 0.6, raw.updateDate);
    const naics = (raw.naicsCodes || [])[0];
    _push(out, "industry", src, naics, naics ? String(naics) : null, 0.6, raw.updateDate);
    _push(out, "lv_country_region_normalized", src, raw.countryIso2, normalizeCountryRegion(raw.countryIso2), 0.6, raw.updateDate);
  }
  return out;
}

function apolloCandidates(raw, objectType) {
  const out = [];
  const src = "apollo";
  if (objectType === "contacts") {
    _push(out, "email", src, raw.email, normalizeEmailBasic(raw.email), apolloEmailAccuracy(raw), raw.updated_at);
    for (const p of raw.phone_numbers || []) {
      if (p.dnc_status || p.doNotCall) continue; // suppress
      const status = p.status || p.status_cd;
      const acc = status === "valid_number" ? 1.0 : 0.5;
      const t = String(p.type || "").toLowerCase();
      const field = t === "mobile" ? "mobilephone" : "phone";
      _push(out, field, src, p.sanitized_number, normalizePhoneAU(p.sanitized_number), acc, raw.updated_at);
    }
    _push(out, "jobtitle", src, raw.title, _norm(raw.title), 0.6, raw.updated_at);
    _push(out, "seniority", src, raw.seniority, _norm(raw.seniority), 0.6, raw.updated_at);
  } else {
    const org = raw.organization || raw.org || raw;
    _push(out, "lv_revenue_band", src, org.annual_revenue, normalizeRevenueBand(org.annual_revenue), 0.6, raw.updated_at);
    _push(out, "lv_employee_band", src, org.estimated_num_employees, normalizeEmployeeBand(org.estimated_num_employees), 0.6, raw.updated_at);
    // Apollo org industry is free-text (no NAICS in this contract) -> lowercase text key.
    _push(out, "industry", src, org.industry, _norm(org.industry), 0.6, raw.updated_at);
  }
  return out;
}

function zoominfoCandidates(raw, objectType) {
  const out = [];
  const src = "zoominfo";
  const recency = raw.validDate || raw.lastUpdatedDate;
  if (objectType === "contacts") {
    const fullMatch = raw.matchStatus === "FULL_MATCH" || raw.matchStatus === undefined;
    // matchStatus != FULL_MATCH drops person fields entirely (§2).
    if (!fullMatch) return out;
    const acc = typeof raw.contactAccuracyScore === "number" ? raw.contactAccuracyScore / 100 : 0.6;
    _push(out, "email", src, raw.email, normalizeEmailBasic(raw.email), acc, recency);
    // Phones: structural 0.8 (no per-field grade) per §2 "mobilePhone present=0.8".
    _push(out, "phone", src, raw.phone, normalizePhoneAU(raw.phone), 0.8, recency);
    _push(out, "mobilephone", src, raw.mobilePhone, normalizePhoneAU(raw.mobilePhone), 0.8, recency);
    _push(out, "jobtitle", src, raw.jobTitle, _norm(raw.jobTitle), acc, recency);
    _push(out, "seniority", src, raw.managementLevel, _norm(raw.managementLevel), acc, recency);
  } else {
    _push(out, "lv_revenue_band", src, raw.revenue != null ? raw.revenue : raw.revenueRange,
      normalizeRevenueBand(raw.revenue != null ? raw.revenue : raw.revenueRange), 0.6, recency);
    _push(out, "lv_employee_band", src, raw.employeeCount != null ? raw.employeeCount : raw.employeeRange,
      normalizeEmployeeBand(raw.employeeCount != null ? raw.employeeCount : raw.employeeRange), 0.6, recency);
    const naics = (raw.naicsCodes || [])[0];
    _push(out, "industry", src, naics || raw.primaryIndustry, naics ? String(naics) : _norm(raw.primaryIndustry), 0.6, recency);
  }
  return out;
}

function _norm(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim().toLowerCase();
  return s === "" ? null : s;
}

const MAPPERS = { lusha: lushaCandidates, apollo: apolloCandidates, zoominfo: zoominfoCandidates };

function toCandidates(providerName, rawResponse, objectType) {
  const mapper = MAPPERS[String(providerName || "").toLowerCase()];
  if (!mapper || !rawResponse) return [];
  return mapper(rawResponse, objectType === "companies" ? "companies" : "contacts");
}

// scoreEnrichment.js — pure-JS field-level best-of-breed scorer for n8n Code nodes.
//
// scoreCandidates(candidates, opts) groups common-shape candidates (from
// normalizeProviders.toCandidates) by canonical `field`, scores EACH candidate
//   value_score = wA·A + wR·R + wG·G + wT·T          (ENRICHMENT-WORKFLOW-PLAN.md §2)
// and returns the argmax per field with full provenance, plus a flat merge-ready
// winners map ({field: value}) that slots straight into mergeContacts.
//
//   A — accuracy   : candidate.accuracy (already provider-derived).
//   R — recency    : 1 - min(ageDays/staleCeiling, 1) from recencyDate.
//                    NO recencyDate -> neutral 0.5 (freshness unknown, not penalised).
//   G — agreement  : fraction of OTHER sources whose normalizedValue equals this one
//                    (cross-check / consensus). Single source -> 0.
//   T — source trust: base rank /100 (zoominfo .85, lusha .80, apollo .75). Tiebreaker.
//
// PURE + DETERMINISTIC: inject `opts.now` (ISO) — no Date.now in the scoring math.
// `opts.mode`: 'scored_all' (default) scores everything given; 'scored_cost_aware'
// scores only sources in `opts.calledSources` (caller owns the early-exit decision).

const DEFAULT_WEIGHTS = { wA: 0.45, wR: 0.2, wG: 0.25, wT: 0.1 };
const DEFAULT_TRUST = { zoominfo: 0.85, lusha: 0.8, apollo: 0.75 };
const DEFAULT_STALE_CEILING = 365;

function _ageDays(recencyDate, nowIso) {
  if (!recencyDate) return null;
  const then = Date.parse(recencyDate);
  const now = Date.parse(nowIso);
  if (Number.isNaN(then) || Number.isNaN(now)) return null;
  return (now - then) / 86400000;
}

function _recency(recencyDate, nowIso, staleCeiling) {
  const age = _ageDays(recencyDate, nowIso);
  if (age === null) return 0.5; // unknown freshness -> neutral
  const ceil = staleCeiling > 0 ? staleCeiling : DEFAULT_STALE_CEILING;
  return 1 - Math.min(age / ceil, 1);
}

function _eq(a, b) {
  if (a === null || a === undefined || b === null || b === undefined) return false;
  return String(a) === String(b);
}

function scoreCandidates(candidates, opts) {
  opts = opts || {};
  const w = Object.assign({}, DEFAULT_WEIGHTS, opts.weights || {});
  const trust = Object.assign({}, DEFAULT_TRUST, opts.trust || {});
  const staleCeilings = opts.staleCeilings || {};
  const nowIso = opts.now || new Date().toISOString();
  const mode = opts.mode || "scored_all";

  let pool = candidates || [];
  if (mode === "scored_cost_aware" && Array.isArray(opts.calledSources)) {
    const called = new Set(opts.calledSources.map((s) => String(s).toLowerCase()));
    pool = pool.filter((c) => called.has(String(c.source).toLowerCase()));
  }

  // Group by canonical field.
  const groups = {};
  for (const c of pool) {
    (groups[c.field] || (groups[c.field] = [])).push(c);
  }

  const best = {};
  const winners = {};

  for (const field of Object.keys(groups)) {
    const group = groups[field];
    const ceil = staleCeilings[field] || DEFAULT_STALE_CEILING;
    let top = null;

    for (const c of group) {
      // Agreement: OTHER candidates (distinct sources) whose normalizedValue matches.
      const agreedBy = [];
      for (const o of group) {
        if (o === c) continue;
        if (o.source === c.source) continue;
        if (_eq(o.normalizedValue, c.normalizedValue)) agreedBy.push(o.source);
      }
      const otherSources = new Set(group.filter((o) => o.source !== c.source).map((o) => o.source));
      const A = c.accuracy;
      const R = _recency(c.recencyDate, nowIso, ceil);
      const G = otherSources.size ? new Set(agreedBy).size / otherSources.size : 0;
      const T = trust[String(c.source).toLowerCase()] != null ? trust[String(c.source).toLowerCase()] : 0.6;
      const score = w.wA * A + w.wR * R + w.wG * G + w.wT * T;

      const cand = {
        field,
        value: c.value,
        normalizedValue: c.normalizedValue,
        source: c.source,
        score,
        components: { A, R, G, T },
        agreedBy: [...new Set(agreedBy)],
      };

      if (top === null || _beats(cand, top, trust)) top = cand;
    }

    best[field] = top;
    winners[field] = top.value;
  }

  return { best, winners };
}

// Deterministic tie-break: higher score, then higher trust, then source name.
function _beats(a, b, trust) {
  if (a.score !== b.score) return a.score > b.score;
  const ta = trust[String(a.source).toLowerCase()] || 0;
  const tb = trust[String(b.source).toLowerCase()] || 0;
  if (ta !== tb) return ta > tb;
  return String(a.source) < String(b.source);
}

// --- n8n wrapper (CLOUD): pull provider responses by node name, score best-per-field ---
function nodeAll(name) { try { return $(name).all(); } catch (e) { return []; } }
const rows = $('Enrichment Gate').all().filter((it) => it.json.action !== "skip");
const lusha = nodeAll('Lusha Enrich');
const apollo = nodeAll('Apollo Match');
const zoominfo = nodeAll('ZoomInfo Enrich');
return rows.map((it, i) => {
  const row = it.json;
  const ot = row.object_type || "contacts";
  const p = {
    lusha: lusha[i] && lusha[i].json,
    apollo: apollo[i] && apollo[i].json,
    zoominfo: zoominfo[i] && zoominfo[i].json,
  };
  const cands = [
    ...toCandidates("lusha", p.lusha, ot),
    ...toCandidates("apollo", p.apollo, ot),
    ...toCandidates("zoominfo", p.zoominfo, ot),
  ];
  const gap_flag = cands.length === 0;
  const { best, winners } = scoreCandidates(cands, { now: new Date().toISOString() });
  return { json: { ...row, providers: p, scored: { best, winners }, gap_flag } };
});

// mergeContacts.js — pure-JS DETERMINISTIC non-clobber merge for n8n Code nodes.
//
// Mirrors the DETERMINISTIC parts of src/merge_policy.py (deterministic_gate +
// source_metadata + staging_property) for a single upload candidate per field.
// NO Haiku / NO Sonnet — the LLM classification/validation stages that merge_policy
// runs after the gate are intentionally omitted here (n8n Code nodes cannot call
// them; escalation happens in a downstream node). So the decision IS the gate's
// decision. Source = "csv" @ confidence 80 (matches src/ingest.py row_to_provider_result).
//
// Email can NEVER land in canonicalPatch on this enrich path (belt-and-braces: the
// manual_protected class + the 95 threshold already prevent it, and an explicit
// guard enforces it regardless of policy edits).

// Default contacts field policy (source of truth: config/field_policy.yaml `contacts`).
const DEFAULT_CONTACT_POLICY = {
  email:        { class: "manual_protected",  min_confidence: 95 },
  phone:        { class: "fill_blank_only",   min_confidence: 80 },
  mobilephone:  { class: "fill_blank_only",   min_confidence: 85 },
  jobtitle:     { class: "stale_refreshable", min_confidence: 75 },
  linkedin_url: { class: "fill_blank_only",   min_confidence: 85 },
  seniority:    { class: "system_owned",      min_confidence: 75 },
  persona_group:{ class: "system_owned",      min_confidence: 75 },
};

function _isBlank(v) {
  return v === null || v === undefined || v === "" ||
         (Array.isArray(v) && v.length === 0);
}

function stagingProperty(provider, field) {
  return `${provider}_${field}`;
}

function _nowIso() {
  return new Date().toISOString();
}

// Deterministic gate — single candidate, mirrors merge_policy.deterministic_gate.
// has_conflict is always false with one candidate, so the conflict branch is dropped.
function _gate(field, currentValue, confidence, policy) {
  const fieldClass = (policy && policy.class) || "fill_blank_only";
  const minConfidence = (policy && policy.min_confidence != null) ? policy.min_confidence : 80;

  if (confidence < minConfidence) {
    return { decision: "needs_review",
             reason: `Best confidence ${confidence} below threshold ${minConfidence}.` };
  }
  if (fieldClass === "manual_protected") {
    return { decision: "stage_only", reason: "Field is manual_protected." };
  }
  if (fieldClass === "review_required") {
    return { decision: "needs_review", reason: "Field requires review." };
  }
  if (fieldClass === "system_owned" || fieldClass === "score_output" || fieldClass === "veto_output") {
    return { decision: "promote", reason: "System-owned field passed confidence threshold." };
  }
  if (fieldClass === "fill_blank_only") {
    if (_isBlank(currentValue)) {
      return { decision: "promote", reason: "Current value blank and candidate passed threshold." };
    }
    return { decision: "stage_only", reason: "Current value exists and field is fill_blank_only." };
  }
  if (fieldClass === "stale_refreshable") {
    if (_isBlank(currentValue)) {
      return { decision: "promote", reason: "Current value blank and candidate passed threshold." };
    }
    return { decision: "needs_review", reason: "Refresh candidate requires review in MVP." };
  }
  return { decision: "stage_only", reason: "Default conservative behavior." };
}

function _statusFor(decision) {
  // Deterministic (no LLM) validation_status from source_registry vocabulary.
  return decision === "needs_review" ? "human_review_required" : "provider_only";
}

// mergeContacts(existingProps, candidateRow, fieldPolicy?, opts?)
//   existingProps: current HubSpot contact properties (the record being enriched)
//   candidateRow:  canonical-keyed upload row (post column-map + normalization)
//   fieldPolicy:   contacts policy block; defaults to DEFAULT_CONTACT_POLICY
//   opts:          { source="csv", confidence=80 }
function mergeContacts(existingProps, candidateRow, fieldPolicy, opts) {
  existingProps = existingProps || {};
  candidateRow = candidateRow || {};
  const policy = fieldPolicy || DEFAULT_CONTACT_POLICY;
  const source = (opts && opts.source) || "csv";
  const confidence = (opts && opts.confidence != null) ? opts.confidence : 80;
  const verifiedAt = _nowIso();

  const canonicalPatch = {};
  const stagingPatch = {};
  const metadataPatch = {};
  const decisions = [];

  for (const field of Object.keys(candidateRow)) {
    const value = candidateRow[field];
    if (_isBlank(value)) continue; // nothing to merge

    const currentValue = existingProps[field];
    const fieldPol = policy[field] || { class: "fill_blank_only", min_confidence: 80 };

    // Always stage the raw candidate under its provider-namespaced key.
    stagingPatch[stagingProperty(source, field)] = value;

    const gate = _gate(field, currentValue, confidence, fieldPol);
    let decision = gate.decision;

    // HARD GUARD: email never promotes to canonical on the enrich path.
    if (field === "email" && decision === "promote") decision = "stage_only";

    const validationStatus = _statusFor(decision);

    // Stamp source metadata for every field with a chosen candidate.
    const meta = {
      [`${field}_source`]: source,
      [`${field}_confidence`]: confidence,
      [`${field}_verified_at`]: verifiedAt,
      [`${field}_validation_status`]: validationStatus,
    };
    Object.assign(metadataPatch, meta);

    if (decision === "promote") {
      canonicalPatch[field] = value;
    }

    decisions.push({
      field,
      current_value: currentValue === undefined ? null : currentValue,
      chosen_value: value,
      source_provider: source,
      decision,
      confidence,
      reason: gate.reason,
      validation_status: validationStatus,
      verified_at: verifiedAt,
    });
  }

  return { canonicalPatch, stagingPatch, metadataPatch, decisions };
}

// --- n8n wrapper: mergeContacts(existingRecord, winners) non-clobber ---
return $input.all().map((it) => {
  const row = it.json;
  if (!row.scored) return { json: { ...row, merge: null } };  // skip branch
  const winners = row.scored.winners || {};
  const candidate = {};
  for (const f of ["email", "mobilephone", "phone", "jobtitle", "seniority", "linkedin_url"]) {
    if (winners[f] != null && String(winners[f]).trim() !== "") candidate[f] = winners[f];
  }
  const merged = mergeContacts(row.existingRecord || {}, candidate, undefined,
                               { source: "waterfall", confidence: 85 });
  return { json: { ...row, merge: merged } };
});

// Decide Action — CLOUD variant.
// Computes action + the HubSpot property patch from the scored+merged winners.
// The IF nodes route create -> HubSpot Create, enrich -> HubSpot Update (GATED).
return $input.all().map((it) => {
  const row = it.json;
  const action = row.action;
  const properties = row.merge
    ? { ...row.merge.canonicalPatch, ...row.merge.stagingPatch, ...row.merge.metadataPatch }
    : {};
  return { json: {
    action,
    object_type: row.object_type || "contacts",
    contact_id: (row.existingRecord && row.existingRecord.hs_object_id) || null,
    gap_flag: row.gap_flag === true,
    properties
  }};
});
